import{z as B,x as i,o,c as p,q as A,j as n,D as E,d as s,s as l,S as r,b as e}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"Stolper–Samuelson","description":"","frontmatter":{"title":"Stolper–Samuelson","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/stolper-samuelson.md","filePath":"econ/stolper-samuelson.md","lastUpdated":1791413859000}'),d={name:"econ/stolper-samuelson.md"};function S(m,a,u,C,c,h){const t=i("Mermaid");return o(),p("div",null,[a[2]||(a[2]=A('<h1 id="stolper–samuelson" tabindex="-1">Stolper–Samuelson <a class="header-anchor" href="#stolper–samuelson" aria-label="Permalink to &quot;Stolper–Samuelson&quot;">​</a></h1><div class="epigraph"><p>一种产品相对价格上升，密集使用的那种要素的实际报酬上升，另一种要素的实际报酬下降——贸易的分配效应可以比国家总增益更刺耳。</p><footer>—— Stolper and Samuelson, Protection and Real Wages, Review of Economic Studies 1941</footer></div><p><a href="/econ/heckscher-ohlin">上一课</a>给出出口方向与 FPE。本课缺口是价格变动如何切分要素报酬。Krugman 下一课引入规模与品种，分配机制会换；本课先钉 \\(2\\times2\\) 的 Stolper–Samuelson（SS）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>自由贸易改变相对商品价格。SS：商品 1 相对价格上升，则资本密集的 1 扩张，劳动密集的 2 收缩（Rybczynski 的对偶），资本实际报酬 \\(r/P\\) 升，劳动实际报酬 \\(w/P\\) 降—— Magnification：要素价格变动比例大于商品价格变动比例。缺口不是再讲 HO 谁出口什么，而是：国家作为整体有贸易增益（上一课），内部可以有确定的输家。保护进口竞争的劳动密集型产品，可以提高该国劳动的实际工资——这是 1941 年论文对着当时美国关税辩论写的。</p><p><span class="marginnote">Jones 的放大效应：\\(\\hat r\\gt \\hat p_1\\gt \\hat p_2\\gt \\hat w\\)（帽子为对数变动）。名义工资甚至可以升，但相对物价篮子仍使实际工资降。要用两套物价说话。</span></p><p><span class="marginnote">数字实例：若商品 1 的相对价格涨 10%，放大效应可能让资本实际报酬涨 15%、劳动实际报酬降 8%——要素价格的摆动幅度比触发它的商品价格更大，「放大」就是字面意思。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>成本等于价格（零利润）：\\(c_1(w,r)=p_1\\)，\\(c_2(w,r)=p_2\\)。商品价格变动沿单位成本函数映射到 \\(w,r\\)。要素密集不逆转时映射可逆。特定要素模型（Jones–Samuelson–Mussa）是对照：短期资本困在行业内，两行业资本报酬可以反向，劳动作为流动要素效应较弱——时间维度上 SS 是长期、两要素都流动。</p>',9)),(o(),n(r,null,{default:E(()=>[l(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E7%9B%B8%E5%AF%B9%E5%95%86%E5%93%81%E4%BB%B7%E6%A0%BC%22%5D%20--%3E%20SS%5B%22%E5%AF%86%E9%9B%86%E8%A6%81%E7%B4%A0%E5%AE%9E%E9%99%85%E6%8A%A5%E9%85%AC%E5%8D%87%22%5D%0A%20%20P%20--%3E%20LOSE%5B%22%E5%8F%A6%E4%B8%80%E8%A6%81%E7%B4%A0%E5%AE%9E%E9%99%85%E6%8A%A5%E9%85%AC%E9%99%8D%22%5D%0A%20%20MAG%5B%22%E6%94%BE%E5%A4%A7%E6%95%88%E5%BA%94%22%5D%20--%3E%20POL%5B%22%E5%88%86%E9%85%8D%E5%86%B2%E7%AA%81%20%3E%20%E6%80%BB%E5%A2%9E%E7%9B%8A%E5%8F%AF%E8%A7%81%E5%BA%A6%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与计量：China shock 后课用通勤区暴露估劳动市场效应，那是设计；SS 是 \\(2\\times2\\) 的符号预测。两者要对：特定要素、技能、不可贸易，都会改谁输谁赢，不能把 SS 当所有贸易冲击的充分统计。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[s("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"机制是零利润加要素密集。贵了的行业要扩张，必须从另一行业抽要素；抽的时候密集使用的要素变得更稀缺，其报酬升得比商品价更狠，才能把单位成本拉到新价格。输家的要素被「赶」进扩张行业，边际产出掉。总饼可以变大（贸易增益），切法可以更不平等。",-1)),(o(),n(r,null,{default:E(()=>[l(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20PUP%5B%22%E5%95%86%E5%93%81%201%EF%BC%88%E8%B5%84%E6%9C%AC%E5%AF%86%E9%9B%86%EF%BC%89%E7%9B%B8%E5%AF%B9%E4%BB%B7%E6%A0%BC%E4%B8%8A%E5%8D%87%22%5D%20--%3E%20EX%5B%22%E8%A1%8C%E4%B8%9A%201%20%E6%89%A9%E5%BC%A0%22%5D%0A%20%20PUP%20--%3E%20SHR%5B%22%E8%A1%8C%E4%B8%9A%202%EF%BC%88%E5%8A%B3%E5%8A%A8%E5%AF%86%E9%9B%86%EF%BC%89%E6%94%B6%E7%BC%A9%22%5D%0A%20%20SHR%20--%3E%20PULL%5B%22%E6%89%A9%E5%BC%A0%E8%A1%8C%E4%B8%9A%E4%BB%8E%E8%A1%8C%E4%B8%9A%202%20%E6%8A%BD%E8%B5%84%E6%9C%AC%E4%B8%8E%E5%8A%B3%E5%8A%A8%22%5D%0A%20%20PULL%20--%3E%20KSC%5B%22%E8%B5%84%E6%9C%AC%E7%9B%B8%E5%AF%B9%E5%8F%98%E7%A8%80%E7%BC%BA%22%5D%0A%20%20PULL%20--%3E%20LAB%5B%22%E5%8A%B3%E5%8A%A8%E7%9B%B8%E5%AF%B9%E5%8F%98%E5%85%85%E8%A3%95%22%5D%0A%20%20KSC%20--%3E%20RUP%5B%22%E8%B5%84%E6%9C%AC%E5%AE%9E%E9%99%85%E6%8A%A5%E9%85%AC%E5%A4%A7%E6%B6%A8%22%5D%0A%20%20LAB%20--%3E%20WDN%5B%22%E5%8A%B3%E5%8A%A8%E5%AE%9E%E9%99%85%E6%8A%A5%E9%85%AC%E4%B8%8B%E9%99%8D%22%5D%0A%20%20RUP%20--%3E%20ZP%5B%22%E5%8D%95%E4%BD%8D%E6%88%90%E6%9C%AC%E8%A2%AB%E6%8B%89%E5%9B%9E%E5%88%B0%E6%96%B0%E4%BB%B7%E6%A0%BC%EF%BC%88%E9%9B%B6%E5%88%A9%E6%B6%A6%EF%BC%89%22%5D%0A%20%20WDN%20--%3E%20ZP%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=A('<p><span class="marginnote">直觉类比：餐厅的招牌菜突然流行（相对价格上升），后厨把人手从小菜台调过去；招牌菜最依赖的掌勺师傅顿时抢手、工钱猛涨，帮工则面临降薪或转岗——一道菜的行情，重写了整个后厨的收入结构。</span></p><p>与<a href="/econ/redistribution-efficiency">再分配</a>精神：有总增益就可以补偿输家。补偿在政治上常常不发生，于是 SS 成为贸易政治的核，而不是「经济学家说有增益所以无输家」。</p><p><span class="marginnote">要素价格均等化是水平：贸易后 \\(w\\) 对齐。SS 是变动：给定贸易条件变动，\\(\\Delta w\\) 的符号。两国同时进入自由贸易，丰裕要素赢、稀缺要素输——与 HO 方向一致。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>多要素下没有简单的「一种商品对应一种要素」；要用成本份额与一般均衡弹性。技能偏向技术与贸易会纠缠，Feenstra 把外包写成有效扩大低技能劳动供给——后课任务。本课不估美国工资不平等的分解。下一课 Krugman：即便要素禀赋相同，规模与偏好多样性也能产生贸易，分配故事换成品种与企业，而不是 \\(w\\) 对 \\(r\\)。</p><p><span class="marginnote">常见误区：初学者容易以为「国家整体受益」就等于人人都受益。SS 恰好说明总增益与内部分配是两回事：赢家的所得可以远超输家的所失，但输家是确定、可辨识的人群——这正是贸易政治长期紧张的结构性来源。</span></p><p>后课默认：相对价格变动按要素密集切分实际报酬，放大效应使要素价动得比商品价更猛。总增益与输家可以同时真。不要用「贸易有增益」否认 SS 的分配。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SS：产品相对价格升 ⇒ 其密集要素实际报酬升、另一要素降。</li><li>放大：要素价格变动比例更大。</li><li>长期两要素流动；短期特定要素符号可不同。</li><li>补偿在理论里可能，在政治里常缺，故有贸易冲突。</li><li>出处：Stolper and Samuelson, <em>RES</em> 1941；Jones 放大效应。</li></ul>',9))])}const _=B(d,[["render",S]]);export{P as __pageData,_ as default};
